 useEffect(()=>{if(tab!=='works')return;let disposed=false;let timer:number|undefined;const tick=async()=>{if(disposed||worksPollingRef.current)return;worksPollingRef.current=true;setWorksBusy(true);let nextDelay=Math.max(30,worksRefreshSeconds)*1000;try{const snapshot=await window.bitpost.request('/works');const items=(snapshot.items||[]) as Work[];setWorks(items);if(snapshot.refresh_seconds)setWorksRefreshSeconds(snapshot.refresh_seconds);const eligible=items.filter(work=>work.url&&work.collect_status!=='collecting'&&work.collect_status!=='skipped');const start=eligible.length?worksBatchOffsetRef.current%eligible.length:0;const batch=eligible.slice(start,start+3);worksBatchOffsetRef.current=eligible.length?(start+batch.length)%eligible.length:0;for(const work of batch){if(disposed)continue;setWorks(v=>v.map(item=>item.id===work.id?{...item,collect_status:'collecting',collect_message:'自动刷新采集中'}:item));try{const updated=await window.bitpost.request(`/works/${work.id}/collect`,{method:'POST'});if(updated?.id)setWorks(v=>v.map(item=>item.id===work.id?updated:item));}catch(e:any){setWorks(v=>v.map(item=>item.id===work.id?{...item,collect_status:'failed',collect_message:e?.message||'自动采集失败'}:item));}}}catch(e:any){const message=e?.message||String(e);if(!disposed){setError(message);setWorks(v=>v.map(item=>item.collect_status==='collecting'?{...item,collect_status:'failed',collect_message:`自动采集未执行：${message}`}:item));nextDelay=10000}}finally{worksPollingRef.current=false;setWorksBusy(false);if(!disposed)timer=window.setTimeout(tick,nextDelay)}};tick();return()=>{disposed=true;if(timer)window.clearTimeout(timer)}},[tab,worksRefreshSeconds]);
 const toggle=(id:string)=>setSelected(v=>v.includes(id)?v.filter(x=>x!==id):[...v,id]); const all=()=>setSelected(filtered.map(p=>p.id)); const none=()=>setSelected([]);
 const loadFolder=async(folder:string)=>{setFolderLoading(v=>({...v,[folder]:true}));try{const files=await window.bitpost.listMediaFolder(folder);const previews=await Promise.all(files.map((file:string)=>window.bitpost.filePreview(file)));setFolderFiles(v=>({...v,[folder]:previews}))}catch(e:any){setFolderFiles(v=>({...v,[folder]:[]}));setError(e?.message||'读取文件夹素材失败')}finally{setFolderLoading(v=>({...v,[folder]:false}))}}; const appendQuickText=(q:Quick,id?:string)=>{if(id){const current=textByProfile[id]??text;setTextByProfile({...textByProfile,[id]:current.trim()?`${current}\n${q.content}`:q.content})}else setText(prev=>prev.trim()?`${prev}\n${q.content}`:q.content)}; const addMediaFile=async(file:string)=>{if(media.includes(file))return;setMedia(v=>[...v,file]);const preview=await window.bitpost.filePreview(file);setAssetInfo(v=>[...v,preview])}; const pick=async()=>{const files=await window.bitpost.pickFiles(folderPath||undefined);for(const file of files)await addMediaFile(file)}; const bindFolder=async()=>{const folder=await window.bitpost.pickFolder();if(folder){const next=Array.from(new Set([...folderPaths,folder]));setFolderPaths(next);localStorage.setItem('bitpost.folderPaths',JSON.stringify(next));setFolderPath(folder);await loadFolder(folder);setExpandedFolders(v=>({...v,[folder]:true}));setError('')}}; const toggleFolder=async(folder:string)=>{const opening=!expandedFolders[folder];setExpandedFolders(v=>({...v,[folder]:!v[folder]}));if(opening&&!folderFiles[folder])await loadFolder(folder)}; const removeFolder=(folder:string)=>{const next=folderPaths.filter(item=>item!==folder);setFolderPaths(next);localStorage.setItem('bitpost.folderPaths',JSON.stringify(next));setFolderFiles(v=>{const copy={...v};delete copy[folder];return copy});setExpandedFolders(v=>{const copy={...v};delete copy[folder];return copy});if(folderPath===folder)setFolderPath(next[0]||'')}; const appendText=(value:string)=>setText(prev=>prev.trim()?`${prev}\n${value}`:value); const distributeTexts=()=>{const lines=bulkText.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(!selected.length){setError('请先选择需要分配文案的窗口');return}if(!lines.length){setError('请输入至少一条文案，每行一条');return}const next={...textByProfile};selected.forEach((id,index)=>{next[id]=lines[index%lines.length]});setTextByProfile(next);setTextMode('per-profile');setError('')};
 const run=async()=>{if(!selected.length){setError('请至少选择一个窗口环境');return}if(!text.trim()&&!media.length){setError('请先填写文案或选择素材');return}const scheduledTimestamp=scheduleAt?Math.floor(new Date(scheduleAt).getTime()/1000):null; if(scheduleType!=='once'&&!scheduledTimestamp){setError('重复发布需要选择首次执行时间');return} const map:any={};selected.forEach((id,index)=>{const assignedMedia=allocationMode==='shared'?media:allocationMode==='roundrobin'?(media.length?[media[index%media.length]]:[]):(manualMediaByProfile[id]||[]);const assignedText=textMode==='shared'?text:(textByProfile[id] ?? text);map[id]={text:assignedText,media:assignedMedia}});try{const created=await window.bitpost.request('/tasks',{method:'POST',body:JSON.stringify({profile_ids:selected,content_by_profile:map,dry_run:dryRun,collect_after_publish:collectAfterPublish,concurrency:2,retry_limit:1,scheduled_at:scheduledTimestamp,schedule_type:scheduleType,schedule_weekdays:scheduleWeekdays})});setRunState({id:created.id,status:'running',phase:'queued',message:'任务已创建，正在排队'});setTab('logs');const started=Date.now();const poll=async()=>{try{const current=await window.bitpost.request(`/tasks/${created.id}`);setRunState({id:created.id,status:current.status,phase:current.phase||'',message:current.last_message||''});const logData=await window.bitpost.request('/logs');setLogs(logData.items||[]);if(current.status==='running'&&Date.now()-started<900000){setTimeout(poll,800)}else{await refresh()}}catch(e:any){setError(e.message)}};setTimeout(poll,300)}catch(e:any){setError(e.message)}};
