function fmtMetric(value:number|null){return value===null||value===undefined?'暂未采集':value.toLocaleString()}
function fmtRate(value:number|null){return value===null||value===undefined?'—':`${value.toLocaleString()}/小时`}
function fmtTime(value:number|null){return value?new Date(value*1000).toLocaleString():'—'}
function WorksTableMonitor({works,busy,refreshSeconds,setRefreshSeconds,onRefresh,onCollect,onSaveLink,onDeleteWorks}:{works:Work[];busy:boolean;refreshSeconds:number;setRefreshSeconds:(v:number)=>void;onRefresh:()=>void;onCollect:(id:string)=>void;onSaveLink:(id:string,url:string)=>void;onDeleteWorks:(ids:string[])=>void}){const [editingLink,setEditingLink]=useState<string|null>(null);const [draftLink,setDraftLink]=useState('');const [selectedWorks,setSelectedWorks]=useState<string[]>([]);const toggleWork=(id:string)=>setSelectedWorks(v=>v.includes(id)?v.filter(x=>x!==id):[...v,id]);const selectAllWorks=()=>setSelectedWorks(selectedWorks.length===works.length?[]:works.map(w=>w.id));const cell=(value:number|null,delta:number|null,hourly:number|null)=><div className="work-table-value"><b>{fmtMetric(value)}</b><small>{fmtMetric(delta)} · {fmtRate(hourly)}</small></div>;return <section className="content works-monitor"><div className="works-toolbar"><div><p className="eyebrow">FACEBOOK CONTENT LIBRARY</p><h2>作品实时监测</h2><p>参考 Facebook 专业内容库，按作品横向查看实时数据。</p></div><div className="works-actions"><button className="outline small danger" disabled={!selectedWorks.length} onClick={()=>{onDeleteWorks(selectedWorks);setSelectedWorks([])}}>删除选中 {selectedWorks.length?`(${selectedWorks.length})`:''}</button><label>自动刷新<select value={refreshSeconds} onChange={e=>setRefreshSeconds(Number(e.target.value))}><option value={600}>10 分钟</option><option value={30}>30 秒</option><option value={60}>60 秒</option></select></label><button className="outline" onClick={onRefresh}><RefreshCw size={15} className={busy?'spin':''}/>立即刷新</button></div></div><div className="works-summary compact"><div><span>监测作品</span><strong>{works.length}</strong></div><div><span>已采集</span><strong>{works.filter(w=>w.collect_status==='collected').length}</strong></div><div><span>待采集</span><strong>{works.filter(w=>!['collected','skipped'].includes(w.collect_status)).length}</strong></div><div><span>刷新周期</span><strong>{refreshSeconds}s</strong></div></div><div className="works-table-shell"><div className="works-table-scroll"><div className="works-table-head"><span><input type="checkbox" checked={works.length>0&&selectedWorks.length===works.length} onChange={selectAllWorks}/> 预览 / 作品</span><span>浏览量</span><span>浏览人数</span><span>互动次数</span><span>点赞数</span><span>播放次数</span><span>评论数</span><span>覆盖人数</span><span>操作</span></div>{works.length?works.map(work=><div className="works-table-row" key={work.id}><div className="work-table-title"><input className="work-select" type="checkbox" checked={selectedWorks.includes(work.id)} onChange={()=>toggleWork(work.id)}/><div className="work-thumb">{work.platform?.slice(0,1)||'F'}</div><div><strong>窗口 #{work.window_seq||'未知'} · {work.account_name||'未知账号'}</strong><small title={work.text_summary}>{work.text_summary||'无文案摘要'}</small><em>{fmtTime(work.published_at)}</em></div></div>{cell(work.views,work.delta_views,work.hourly_views)}{cell(work.reach,work.delta_reach,work.hourly_reach)}{cell(work.interactions,work.delta_interactions,work.hourly_interactions)}{cell(work.likes,work.delta_likes,work.hourly_likes)}{cell(work.plays,work.delta_plays,work.hourly_plays)}{cell(work.comments,work.delta_comments,work.hourly_comments)}{cell(work.reach,work.delta_reach,work.hourly_reach)}<div className="work-table-actions"><span className={'work-status '+(['collected','skipped'].includes(work.collect_status)?'ok':'pending')}>{work.collect_status==='collected'?'已采集':work.collect_status==='skipped'?'无需采集':work.collect_status==='collecting'?'采集中':'待采集'}</span><small className="work-table-collected">{work.last_collected_at?`上次采集 ${fmtTime(work.last_collected_at)}`:'尚未成功采集'}</small>{editingLink===work.id?<><input className="work-link-input" value={draftLink} onChange={e=>setDraftLink(e.target.value)} placeholder="作品或 Insights 链接"/><button className="outline small" onClick={()=>{onSaveLink(work.id,draftLink);setEditingLink(null)}}>保存</button></>:<><button className="outline small" onClick={()=>{setDraftLink(work.url||'');setEditingLink(work.id)}}>{work.url?'编辑链接':'绑定链接'}</button>{work.collect_status!=='skipped'&&<button className="outline small" disabled={work.collect_status==='collecting'} onClick={()=>onCollect(work.id)}>{work.collect_status==='collecting'?'采集中…':'手动采集'}</button>}<button className="outline small danger" onClick={()=>{onDeleteWorks([work.id]);setSelectedWorks(v=>v.filter(x=>x!==work.id))}}>删除记录</button></>}</div></div>):<div className="empty-state works-empty"><TimerReset size={30}/><span>暂无已登记作品</span><small>任务中心发布成功后，作品会出现在这里。</small></div>}</div></div></section>}

function WorksMonitor({works,busy,refreshSeconds,setRefreshSeconds,onRefresh,onCollect,onSaveLink}:{works:Work[];busy:boolean;refreshSeconds:number;setRefreshSeconds:(v:number)=>void;onRefresh:()=>void;onCollect:(id:string)=>void;onSaveLink:(id:string,url:string)=>void}){const [editingLink,setEditingLink]=useState<string|null>(null);const [draftLink,setDraftLink]=useState('');return <section className="content works-monitor"><div className="works-toolbar"><div><p className="eyebrow">FACEBOOK WORKS INSIGHT</p><h2>作品实时监测</h2><p>自动登记任务中心发布成功的作品，并保留最近一次有效采集数据。</p></div><div className="works-actions"><label>自动刷新<select value={refreshSeconds} onChange={e=>setRefreshSeconds(Number(e.target.value))}><option value={600}>10 分钟</option><option value={30}>30 秒</option><option value={60}>60 秒</option></select></label><button className="outline" onClick={onRefresh}><RefreshCw size={15} className={busy?'spin':''}/>立即刷新</button></div></div><div className="works-summary"><div><span>监测作品</span><strong>{works.length}</strong></div><div><span>已采集</span><strong>{works.filter(w=>w.collect_status==='collected').length}</strong></div><div><span>待采集</span><strong>{works.filter(w=>!['collected','skipped'].includes(w.collect_status)).length}</strong></div><div><span>刷新周期</span><strong>{refreshSeconds}s</strong></div></div><div className="works-list">{works.length?works.map(work=><article className="work-card" key={work.id}><div className="work-card-head"><div><span className="work-platform">{work.platform}</span><h3>窗口 #{work.window_seq||'未知'} · {work.account_name}</h3><small>发布时间：{fmtTime(work.published_at)} · 任务 {work.task_id}</small></div><div className={'work-status '+(['collected','skipped'].includes(work.collect_status)?'ok':'pending')}>{work.collect_status==='collected'?'已采集':work.collect_status==='skipped'?'无需采集':work.collect_status==='collecting'?'采集中':work.collect_status==='failed'?'采集失败':'暂未采集'}</div></div><p className="work-summary">{work.text_summary||'无文案摘要'}</p><div className="work-link">{editingLink===work.id?<><input className="work-link-input" value={draftLink} onChange={e=>setDraftLink(e.target.value)} placeholder="粘贴 Facebook 具体作品链接"/><button className="outline small" onClick={()=>{onSaveLink(work.id,draftLink);setEditingLink(null)}}>保存链接</button></>:<>{work.url&&<><ExternalLink size={14}/><a href={work.url} target="_blank" rel="noreferrer">打开作品/页面</a></>}<button className="outline small" onClick={()=>{setDraftLink(work.url||'');setEditingLink(work.id)}}>{work.url?'编辑链接':'绑定作品链接'}</button></>}</div><div className="work-metrics-vertical"><div className="metric-row-head"><span>指标</span><span>当前数据</span><span>距上次采集</span><span>平均每小时</span></div><div className="metric-row"><span><Eye size={14}/>浏览量</span><b>{fmtMetric(work.views)}</b><small>{fmtMetric(work.delta_views)}</small><small>{fmtRate(work.hourly_views)}</small></div><div className="metric-row"><span><Heart size={14}/>点赞</span><b>{fmtMetric(work.likes)}</b><small>{fmtMetric(work.delta_likes)}</small><small>{fmtRate(work.hourly_likes)}</small></div><div className="metric-row"><span><MessageCircle size={14}/>评论</span><b>{fmtMetric(work.comments)}</b><small>{fmtMetric(work.delta_comments)}</small><small>{fmtRate(work.hourly_comments)}</small></div><div className="metric-row"><span><Activity size={14}/>互动次数</span><b>{fmtMetric(work.interactions)}</b><small>{fmtMetric(work.delta_interactions)}</small><small>{fmtRate(work.hourly_interactions)}</small></div><div className="metric-row"><span><Play size={14}/>播放次数</span><b>{fmtMetric(work.plays)}</b><small>{fmtMetric(work.delta_plays)}</small><small>{fmtRate(work.hourly_plays)}</small></div><div className="metric-row"><span><Gauge size={14}/>覆盖人数</span><b>{fmtMetric(work.reach)}</b><small>{fmtMetric(work.delta_reach)}</small><small>{fmtRate(work.hourly_reach)}</small></div></div><div className="work-card-foot"><span>{work.last_collected_at?`上次采集：${fmtTime(work.last_collected_at)}`:work.collect_message||'暂未采集'}</span>{work.collect_status!=='skipped'&&<button className="outline small" disabled={work.collect_status==='collecting'} onClick={()=>onCollect(work.id)}><TimerReset size={13}/>{work.collect_status==='collecting'?'采集中…':'手动采集'}</button>}</div></article>):<div className="empty-state works-empty"><TimerReset size={30}/><span>暂无已登记作品</span><small>任务中心发布成功后，作品会自动出现在这里。</small></div>}</div></section>}
function TaskRecords({tasks,onRefresh,onRetry}:{tasks:any[];onRefresh:()=>void;onRetry:(id:string)=>Promise<void>}){const failedTasks=tasks.filter(task=>task.status==='failed');const [selected,setSelected]=useState<string[]>([]);const selectedFailed=failedTasks.filter(task=>selected.includes(task.id));const allSelected=failedTasks.length>0&&selectedFailed.length===failedTasks.length;const toggle=(id:string)=>setSelected(v=>v.includes(id)?v.filter(item=>item!==id):[...v,id]);const retrySelected=async()=>{for(const task of selectedFailed)await onRetry(task.id);setSelected([]);};return <section className="content"><div className="works-toolbar"><div><p className="eyebrow">TASK RECORDS</p><h2>任务记录</h2><p>定时任务、执行结果和失败任务会长期保留；失败任务的文案与素材可再次重发。</p></div><div className="works-actions"><button className="outline" onClick={onRefresh}><RefreshCw size={15}/>刷新记录</button>{failedTasks.length>0&&<><button className="outline small" onClick={()=>setSelected(allSelected?[]:failedTasks.map(task=>task.id))}>{allSelected?'取消全选失败任务':'全选失败任务'}</button><button className="primary small" disabled={!selected.length} onClick={retrySelected}>一键重发{selected.length?` (${selected.length})`:''}</button></>}</div></div><div className="works-list">{tasks.length?tasks.map(task=><article className="work-card" key={task.id}><div className="work-card-head"><div style={{display:'flex',gap:'10px',alignItems:'flex-start'}}>{task.status==='failed'&&<input type="checkbox" checked={selected.includes(task.id)} onChange={()=>toggle(task.id)} style={{marginTop:'5px'}}/>}<div><span className="work-platform">{task.schedule_type==='daily'?'每日':task.schedule_type==='weekly'?'每周':task.status==='scheduled'?'一次性定时':'立即任务'}</span><h3>任务 {task.id}</h3><small>{task.profile_ids?.length||0} 个窗口 · {task.scheduled_at?`计划 ${new Date(task.scheduled_at*1000).toLocaleString()}`:'立即执行'}</small></div></div><div className={'work-status '+(task.status==='completed'?'ok':task.status==='failed'?'pending':'ok')}>{task.status==='completed'?'已完成':task.status==='failed'?'失败待重发':task.status==='scheduled'?'已排期':task.status==='running'?'执行中':task.status==='cancelled'?'已取消':task.status}</div></div><p className="work-summary">{task.last_message||'暂无任务说明'}</p>{task.status==='failed'&&<div className="work-card-foot"><span>已保留文案和素材路径</span><button className="primary small" onClick={()=>onRetry(task.id)}>再次重发</button></div>}</article>):<div className="empty-state works-empty"><ClipboardList size={30}/><span>暂无任务记录</span><small>创建任务后，记录会显示在这里。</small></div>}</div></section>}
function LogsPanel({logs,code,setCode}:any){return <section className="content logs-layout"><div className="panel logs-box"><div className="panel-title"><div><h3>实时运行日志</h3><p>任务执行过程、重试和结果会按窗口维度记录。</p></div><button className="outline small" onClick={()=>navigator.clipboard?.writeText(logs.map((l:Log)=>`${l.time} [${l.level}] ${l.message}`).join('\n'))}><ClipboardList size={15}/>复制日志</button></div><div className="log-console">{logs.map((l:Log,i:number)=><div className="log-line" key={i}><span>{l.time}</span><b className={l.level.toLowerCase()}>{l.level}</b><p>{l.message}</p></div>)}</div></div><div className="panel code-box"><div className="panel-title"><div><h3>代码查看与修改</h3><p>建议使用 VS Code 保存实际文件</p></div><Code2 size={19}/></div><textarea className="code-editor" value={code} onChange={e=>setCode(e.target.value)} placeholder="粘贴代码进行临时编辑……"/><button className="primary wide"><Save size={15}/>保存修改</button></div></section>}
function ConnectionModal({onClose,onTest}:{onClose:()=>void;onTest:()=>void}){return <div className="modal-backdrop" onClick={onClose}><div className="settings-modal" onClick={e=>e.stopPropagation()}><div className="modal-head"><div><h3>连接设置</h3><p>查看本地服务地址并测试 BitBrowser 连接。</p></div><button className="modal-close" onClick={onClose}>×</button></div><label>Python 本地服务地址<input value="http://127.0.0.1:8765" readOnly/></label><label>BitBrowser 本地接口地址<input value="http://127.0.0.1:54345" readOnly/></label><div className="settings-note">如果测试失败，请先确认 Python 后端在 8765 端口运行，并且 BitBrowser 本地服务端口为 54345。</div><div className="modal-actions"><button className="outline" onClick={onClose}>关闭</button><button className="primary" onClick={onTest}><RefreshCw size={15}/>测试连接</button></div></div></div>}

createRoot(document.getElementById('root')!).render(<App/>);
